import {queryBuilding,toolSchema} from './query-tools.mjs';
import {equipmentTools,executeEquipmentTool} from './equipment-state.mjs';
const $=id=>document.getElementById(id),api='https://api.groq.com/openai/v1';let history=[],busy=false,abort=null,version=null,transcript=[],revision=0;
$('ai-prompt').value=window.COGNITIVE_SYSTEM_PROMPT||'';
$('ai-prompt-reset').onclick=()=>{$('ai-prompt').value=window.COGNITIVE_SYSTEM_PROMPT||'';};
$('ai-key').value=window.COGNITIVE_GROQ_KEY||'';
function message(role,text){transcript.push({role,text});revision++;const item=document.createElement('div');item.className='ai-msg '+role;item.textContent=text;$('ai-log').append(item);$('ai-log').scrollTop=$('ai-log').scrollHeight;}
async function request(path,body){const r=await fetch(api+path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+$('ai-key').value.trim(),'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined,signal:abort?.signal||AbortSignal.timeout(60000)});const data=await r.json();if(!r.ok)throw Error(data.error?.message||'Groq HTTP '+r.status);return data;}
$('ai-open').onclick=()=>{$('ai-panel').hidden=!$('ai-panel').hidden;};$('ai-close').onclick=()=>$('ai-panel').hidden=true;
$('ai-models').onclick=async()=>{try{$('ai-status').textContent='Loading Groq models…';const result=await request('/models');const current=$('ai-model').value;$('ai-options').replaceChildren();for(const m of result.data.filter(m=>m.active!==false).sort((a,b)=>a.id.localeCompare(b.id))){const o=document.createElement('option');o.value=m.id;$('ai-options').append(o);}$('ai-model').value=current||'openai/gpt-oss-20b';$('ai-status').textContent='Models refreshed. Choose a chat model supporting tool calls; audio models cannot answer building queries.';}catch(e){$('ai-status').textContent=e.message;}};
$('ai-clear').onclick=()=>{if(busy)return;history=[];transcript=[];revision++;$('ai-log').replaceChildren();message('assistant','Ask about floors, components, exported properties or current room readings.');};
$('ai-stop').onclick=()=>abort?.abort();
window.addEventListener('message',e=>{if(e.source!==$('viewer').contentWindow||e.origin!==location.origin)return;if(e.data?.type==='viewer-loaded'){abort?.abort();history=[];version=null;transcript=[];revision++;$('ai-log').replaceChildren();message('assistant','Model ready. Ask about the IFC, or control simulated devices: “Turn on all equipment in Room 110” or “Set the AC to level 8.”');}});
for(const b of document.querySelectorAll('[data-question]'))b.onclick=()=>{$('ai-input').value=b.dataset.question;};
async function ask(question){if(busy)throw Error('An answer is already in progress.');const q=String(question).trim();if(!q)return '';const twin=$('viewer').contentWindow?.cognitiveTwin;if(!twin){throw Error('Wait for the model to finish loading.');}if(version!==twin){history=[];version=twin;}const snapshot=twin.snapshot();busy=true;abort=new AbortController();const timeout=setTimeout(()=>abort.abort(),90000);$('ai-send').disabled=true;$('ai-stop').hidden=false;$('ai-input').value='';message('user',q);
 const system={role:'system',content:$('ai-prompt').value.trim()||window.COGNITIVE_SYSTEM_PROMPT};
 const messages=[system,...history.slice(-12),{role:'user',content:q}];try{let final='';for(let turn=0;turn<10;turn++){$('ai-status').textContent=turn?'Checking IFC evidence…':'Thinking…';const d=await request('/chat/completions',{model:$('ai-model').value.trim(),messages,tools:[...toolSchema,...equipmentTools],tool_choice:turn===0?'required':'auto',temperature:.1,max_tokens:1800});const m=d.choices?.[0]?.message;if(!m)throw Error('No response from the selected model.');messages.push(m);if(!m.tool_calls?.length){final=m.content||'No text returned. Try a different chat model.';break;}
 for(const t of m.tool_calls){let result;try{const args=JSON.parse(t.function.arguments);result=t.function.name==='query_building'?queryBuilding(twin.snapshot(),args):executeEquipmentTool(twin,t.function.name,args);}catch(err){result={error:err.message};}const detail=document.createElement('details'),summary=document.createElement('summary'),pre=document.createElement('pre');summary.textContent=t.function.name+' · '+t.function.arguments;pre.textContent=JSON.stringify(result,null,2);detail.append(summary,pre);$('ai-log').append(detail);messages.push({role:'tool',tool_call_id:t.id,content:JSON.stringify(result)});}}
 if(!final)throw Error('Query reached its tool limit. Please narrow the floor, room or category.');message('assistant',final);history.push({role:'user',content:q},{role:'assistant',content:final});$('ai-status').textContent='Answered using '+snapshot.name+' · '+new Date(snapshot.timestamp).toLocaleTimeString();window.CognitiveVoice?.onAnswer(final);return final;
 }catch(err){message('assistant',err.name==='AbortError'?'Request stopped or timed out.':err.message);$('ai-status').textContent='Try again or select a different Groq tool-capable chat model.';throw err;}finally{clearTimeout(timeout);busy=false;abort=null;$('ai-send').disabled=false;$('ai-stop').hidden=true;}}

$('ai-form').onsubmit=async e=>{e.preventDefault();try{await ask($('ai-input').value);}catch(e){if(!busy)$('ai-status').textContent=e.message;}};
window.CognitiveAssistant={ask,stop:()=>abort?.abort(),state:()=>({busy,revision,messages:transcript.map(m=>({...m})),model:$('ai-model').value}),clear:()=>$('ai-clear').onclick()};
